/// Describe model limits and the selected format's opening-hand policy.
pub(super) fn for_deck(deck: &SimDeck) -> Vec<String> {
    let mut limits: Vec<String> = MODEL_LIMITS
        .iter()
        .map(|limit| (*limit).to_string())
        .collect();
    limits.push(format!(
        "Action sequences are bounded at {MAX_LOOP_PASSES} passes. A work limit with unresolved work marks the game incomplete. Finishing exactly at the limit does not. One token-creation effect creates at most eight objects; any uncreated objects mark the game incomplete. Scaled draws do not have an eight-card ceiling. Repeated mana actions at a cap can flag suspected infinite mana, but do not prove a legal infinite combo."
    ));
    limits.push(format!(
        "Starting life is {} for the player and each of the {} modeled opponent seats.",
        deck.rules.starting_life,
        deck.format.life_loss_mult()
    ));
    match deck.rules.mulligan {
        MulliganPolicy::FreeRedraw { land_band: (lo, hi) } => limits.push(format!(
            "One free mulligan when the opening hand has fewer than {lo} or more than {hi} land-capable cards. The redraw is kept without bottoming cards."
        )),
        MulliganPolicy::London => limits.push(
            "London mulligan: full seven-card hands redraw outside the two-to-five-land band, up to six redraws. The kept hand bottoms one card per redraw. The bottoming policy removes a land at four or more lands, otherwise a spell when available. It does not evaluate every keep choice.".to_string(),
        ),
    }
    if deck.commanders.is_empty() {
        limits.push("This deck has no commander zone. Constructed games on the play skip the first-turn draw.".to_string());
    } else {
        limits.push("The commander starts in the command zone. Each previous cast from that zone adds {2} to its next command-zone cast. This cost rule does not supply opponent removal or a general commander-zone movement policy.".to_string());
    }
    limits.push("A companion is the first bench card with the Companion keyword. Its deck condition is assumed legal. It starts outside the library; one payment of {3} puts it into hand.".to_string());
    limits
}
